<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence;
use App\Application\Exceptions\OperationConflict;
use App\Application\Read\Page;
use App\Application\Repositories\PricingRepository;
use App\Domain\Pricing\Decimal;
use PDO;

final class PdoPricingRepository extends PdoRepository implements PricingRepository
{
    public function prices(string $search,?int $branchId,?int $listId,?bool $active,int $limit,int $offset):Page
    {
        [$limit,$offset]=self::pageBounds($limit,$offset);$where=[];$params=[];$search=trim($search);
        if($search!==''){if(strlen($search)>120)throw new \InvalidArgumentException('La búsqueda es demasiado larga.');$where[]='(pv.sku LIKE :q OR p.name LIKE :q OR pv.name LIKE :q)';$params['q']='%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],$search).'%';}
        if($branchId!==null){$where[]='bp.branch_id=:branch';$params['branch']=self::id($branchId);}if($listId!==null){$where[]='bp.price_list_id=:list';$params['list']=self::id($listId);}if($active!==null){$where[]='bp.is_active=:active';$params['active']=$active?1:0;}
        return $this->safely(function()use($where,$params,$limit,$offset):Page{$sql='SELECT bp.*,b.code branch_code,b.name branch_name,p.name product_name,pv.sku,pv.name variant_name,pl.code list_code,pl.name list_name,tc.code tax_code,tc.name tax_name FROM branch_variant_prices bp INNER JOIN branches b ON b.id=bp.branch_id INNER JOIN product_variants pv ON pv.id=bp.variant_id INNER JOIN products p ON p.id=pv.product_id INNER JOIN price_lists pl ON pl.id=bp.price_list_id INNER JOIN tax_categories tc ON tc.id=bp.tax_category_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY p.name,pv.sku,b.name,pl.name,bp.valid_from DESC,bp.id DESC LIMIT :limit OFFSET :offset';$s=$this->pdo()->prepare($sql);foreach($params as$k=>$v)$s->bindValue($k,$v,is_int($v)?PDO::PARAM_INT:PDO::PARAM_STR);$s->bindValue('limit',$limit+1,PDO::PARAM_INT);$s->bindValue('offset',$offset,PDO::PARAM_INT);$s->execute();$rows=$s->fetchAll();$more=count($rows)>$limit;if($more)array_pop($rows);return new Page($rows,$limit,$offset,$more);},'Unable to read prices.');
    }
    public function findPrice(int $id,bool $lock=false):?array{return $this->one('SELECT * FROM branch_variant_prices WHERE id=:id'.($lock?' FOR UPDATE':''),['id'=>self::id($id)]);}
    public function priceHistory(int $priceId):array{$s=$this->pdo()->prepare('SELECT ph.*,u.display_name actor_name FROM price_history ph INNER JOIN users u ON u.id=ph.actor_user_id WHERE ph.price_id=:id ORDER BY ph.created_at DESC,ph.id DESC LIMIT 250');$s->execute(['id'=>self::id($priceId)]);return$s->fetchAll();}
    public function createPrice(array $d):array{return $this->safely(function()use($d):array{$s=$this->pdo()->prepare('INSERT INTO branch_variant_prices(branch_id,variant_id,price_list_id,tax_category_id,amount,tax_included,valid_from,valid_until,is_active,created_by,updated_by) VALUES(:branch_id,:variant_id,:price_list_id,:tax_category_id,:amount,:tax_included,:valid_from,:valid_until,0,:created_by,:updated_by)');$actor=$d['actor_id'];unset($d['actor_id']);$d['created_by']=$actor;$d['updated_by']=$actor;$s->execute($d);return$this->findPrice($this->insertedId(),true)??throw new \RuntimeException();},'Unable to create price.');}
    public function updatePrice(int $id,int $expectedVersion,array $d):array{return $this->safely(function()use($id,$expectedVersion,$d):array{$d['id']=self::id($id);$d['version']=$expectedVersion;$s=$this->pdo()->prepare('UPDATE branch_variant_prices SET branch_id=:branch_id,variant_id=:variant_id,price_list_id=:price_list_id,tax_category_id=:tax_category_id,amount=:amount,tax_included=:tax_included,valid_from=:valid_from,valid_until=:valid_until,updated_by=:actor_id,lock_version=lock_version+1 WHERE id=:id AND lock_version=:version');$s->execute($d);if($s->rowCount()!==1)throw new OperationConflict('El precio cambió en otra sesión. Recarga antes de guardar.');return$this->findPrice($id,true)??throw new \RuntimeException();},'Unable to update price.');}
    public function setPriceActive(int $id,int $expectedVersion,bool $active,int $actorId):array{return $this->safely(function()use($id,$expectedVersion,$active,$actorId):array{$s=$this->pdo()->prepare('UPDATE branch_variant_prices SET is_active=:active,updated_by=:actor,lock_version=lock_version+1 WHERE id=:id AND lock_version=:version');$s->execute(['active'=>$active?1:0,'actor'=>self::id($actorId),'id'=>self::id($id),'version'=>$expectedVersion]);if($s->rowCount()!==1)throw new OperationConflict('El precio cambió en otra sesión. Recarga antes de continuar.');return$this->findPrice($id,true)??throw new \RuntimeException();},'Unable to change price status.');}
    public function lockPriceScope(int $branchId,int $variantId,int $listId):void{foreach([['branches',$branchId],['product_variants',$variantId],['price_lists',$listId]]as[$table,$id]){$s=$this->pdo()->prepare("SELECT id FROM $table WHERE id=:id FOR UPDATE");$s->execute(['id'=>self::id($id)]);if($s->fetchColumn()===false)throw new \InvalidArgumentException('La referencia comercial seleccionada no existe.');}}
    public function conflictingPrice(int $branchId,int $variantId,int $listId,string $from,?string $until,?int $excludeId=null):bool{return$this->periodOverlap('branch_variant_prices','branch_id=:branch AND variant_id=:variant AND price_list_id=:list',['branch'=>$branchId,'variant'=>$variantId,'list'=>$listId],$from,$until,$excludeId);}
    public function recordPriceHistory(int $priceId,int $actorId,string $action,?array $previous,array $current):void{$s=$this->pdo()->prepare('INSERT INTO price_history(price_id,actor_user_id,action,previous_json,current_json) VALUES(:price,:actor,:action,:previous,:current)');$s->execute(['price'=>self::id($priceId),'actor'=>self::id($actorId),'action'=>$action,'previous'=>$previous===null?null:json_encode($previous,JSON_THROW_ON_ERROR),'current'=>json_encode($current,JSON_THROW_ON_ERROR)]);}
    public function effectivePrice(int $branchId,int $variantId,int $listId,string $date):?array
    {
        $requested=$this->effectiveExplicit($branchId,$variantId,$listId,$date);if($requested!==null){$requested['source']='explicit';return$this->withTax($requested,$date);}
        $list=$this->one('SELECT id,is_public FROM price_lists WHERE id=:id AND is_active=1',['id'=>self::id($listId)]);if($list===null||((int)$list['is_public'])===1)return null;
        $public=$this->one('SELECT id FROM price_lists WHERE is_public=1 AND is_active=1',[]);if($public===null)return null;$base=$this->effectiveExplicit($branchId,$variantId,(int)$public['id'],$date);if($base===null)return null;
        $rule=$this->one('SELECT discount_rate FROM price_list_rules WHERE price_list_id=:list AND is_active=1 AND valid_from<=:date AND(valid_until IS NULL OR valid_until>=:date2) ORDER BY valid_from DESC,id DESC LIMIT 1',['list'=>$listId,'date'=>$date,'date2'=>$date]);if($rule===null)return null;
        $amount=Decimal::parse((string)$base['amount'],4)->multiply(Decimal::parse('100',0)->subtract(Decimal::parse((string)$rule['discount_rate'],4)))->divide(Decimal::parse('100',0),4);$base['amount']=$amount->format(4);$base['price_list_id']=$listId;$base['source']='list_rule';$base['discount_rate']=$rule['discount_rate'];return$this->withTax($base,$date);
    }
    private function effectiveExplicit(int$b,int$v,int$l,string$d):?array{return$this->one('SELECT bp.*,pl.code list_code,pl.name list_name,tc.code tax_code,tc.name tax_name FROM branch_variant_prices bp INNER JOIN price_lists pl ON pl.id=bp.price_list_id AND pl.is_active=1 INNER JOIN tax_categories tc ON tc.id=bp.tax_category_id AND tc.is_active=1 WHERE bp.branch_id=:branch AND bp.variant_id=:variant AND bp.price_list_id=:list AND bp.is_active=1 AND bp.valid_from<=:date AND(bp.valid_until IS NULL OR bp.valid_until>=:date2) ORDER BY bp.valid_from DESC,bp.id DESC LIMIT 1',['branch'=>self::id($b),'variant'=>self::id($v),'list'=>self::id($l),'date'=>$d,'date2'=>$d]);}
    private function withTax(array$row,string$date):?array{$rate=$this->one('SELECT rate FROM tax_rates WHERE tax_category_id=:category AND is_active=1 AND valid_from<=:date AND(valid_until IS NULL OR valid_until>=:date2) ORDER BY valid_from DESC,id DESC LIMIT 1',['category'=>$row['tax_category_id'],'date'=>$date,'date2'=>$date]);if($rate===null)return null;$row['tax_rate']=$rate['rate'];return$row;}
    public function variants(string$search=''):array{$search=trim($search);$term='%'.$search.'%';$s=$this->pdo()->prepare('SELECT pv.id,pv.sku,pv.name,p.name product_name,pv.is_active FROM product_variants pv INNER JOIN products p ON p.id=pv.product_id WHERE(:empty=1 OR pv.sku LIKE :q1 OR pv.name LIKE :q2 OR p.name LIKE :q3) ORDER BY p.name,pv.sku LIMIT 500');$s->execute(['empty'=>$search===''?1:0,'q1'=>$term,'q2'=>$term,'q3'=>$term]);return$s->fetchAll();}
    public function branches():array{return$this->pdo()->query('SELECT id,code,name,is_active FROM branches ORDER BY name,id LIMIT 1000')->fetchAll();}
    public function priceLists(bool$all=true):array{return$this->pdo()->query('SELECT * FROM price_lists'.($all?'':' WHERE is_active=1').' ORDER BY is_public DESC,name,id LIMIT 1000')->fetchAll();}
    public function taxCategories(bool$all=true):array{return$this->pdo()->query('SELECT * FROM tax_categories'.($all?'':' WHERE is_active=1').' ORDER BY name,id LIMIT 1000')->fetchAll();}
    public function createNamed(string$table,array$d):int{$this->assertTable($table,['tax_categories','price_lists']);$public=$table==='price_lists'?',is_public':'';$publicValue=$table==='price_lists'?',:public':'';$sql="INSERT INTO $table(code,name,description$public,is_active) VALUES(:code,:name,:description$publicValue,0)";return$this->safely(function()use($sql,$d):int{$s=$this->pdo()->prepare($sql);$s->execute($d);return$this->insertedId();},'Unable to create pricing configuration.');}
    public function setNamedStatus(string$table,int$id,int$expectedVersion,bool$active):void{$this->assertTable($table,['tax_categories','price_lists']);$s=$this->pdo()->prepare("UPDATE $table SET is_active=:active,lock_version=lock_version+1 WHERE id=:id AND lock_version=:version");$s->execute(['active'=>$active?1:0,'id'=>self::id($id),'version'=>$expectedVersion]);if($s->rowCount()!==1)throw new OperationConflict('La configuración cambió en otra sesión.');}
    public function createPeriod(string$table,string$foreignKey,int$parentId,string$rateField,string$rate,string$from,?string$until):int{$this->assertPeriod($table,$foreignKey,$rateField);return$this->safely(function()use($table,$foreignKey,$parentId,$rateField,$rate,$from,$until):int{$s=$this->pdo()->prepare("INSERT INTO $table($foreignKey,$rateField,valid_from,valid_until,is_active) VALUES(:parent,:rate,:from,:until,0)");$s->execute(['parent'=>self::id($parentId),'rate'=>$rate,'from'=>$from,'until'=>$until]);return$this->insertedId();},'Unable to create effective rule.');}
    public function setPeriodStatus(string$table,int$id,int$expectedVersion,bool$active):void{$this->assertTable($table,['tax_rates','price_list_rules']);$s=$this->pdo()->prepare("UPDATE $table SET is_active=:active,lock_version=lock_version+1 WHERE id=:id AND lock_version=:version");$s->execute(['active'=>$active?1:0,'id'=>self::id($id),'version'=>$expectedVersion]);if($s->rowCount()!==1)throw new OperationConflict('La regla cambió en otra sesión.');}
    public function findPeriod(string$table,int$id,bool$lock=false):?array{$this->assertTable($table,['tax_rates','price_list_rules']);return$this->one("SELECT * FROM $table WHERE id=:id".($lock?' FOR UPDATE':''),['id'=>self::id($id)]);}
    public function periodConflict(string$table,string$foreignKey,int$parentId,string$from,?string$until,?int$excludeId=null):bool{$this->assertTable($table,['tax_rates','price_list_rules']);if(!in_array($foreignKey,['tax_category_id','price_list_id'],true))throw new \InvalidArgumentException();return$this->periodOverlap($table,"$foreignKey=:parent",['parent'=>$parentId],$from,$until,$excludeId);}
    public function taxRates():array{return$this->pdo()->query('SELECT tr.*,tc.code category_code,tc.name category_name FROM tax_rates tr INNER JOIN tax_categories tc ON tc.id=tr.tax_category_id ORDER BY tc.name,tr.valid_from DESC,tr.id DESC LIMIT 1000')->fetchAll();}
    public function listRules():array{return$this->pdo()->query('SELECT pr.*,pl.code list_code,pl.name list_name FROM price_list_rules pr INNER JOIN price_lists pl ON pl.id=pr.price_list_id ORDER BY pl.name,pr.valid_from DESC,pr.id DESC LIMIT 1000')->fetchAll();}
    public function discountPolicies():array{return$this->pdo()->query('SELECT dp.*,b.code branch_code,b.name branch_name FROM discount_policies dp INNER JOIN branches b ON b.id=dp.branch_id ORDER BY b.name,b.id LIMIT 1000')->fetchAll();}
    public function saveDiscountPolicy(int$branchId,string$rate,?int$expectedVersion):void{$branchId=self::id($branchId);if($expectedVersion===null){$s=$this->pdo()->prepare('INSERT INTO discount_policies(branch_id,seller_limit_rate,is_active) VALUES(:branch,:rate,0)');$s->execute(['branch'=>$branchId,'rate'=>$rate]);return;}$s=$this->pdo()->prepare('UPDATE discount_policies SET seller_limit_rate=:rate,lock_version=lock_version+1 WHERE branch_id=:branch AND lock_version=:version');$s->execute(['rate'=>$rate,'branch'=>$branchId,'version'=>$expectedVersion]);if($s->rowCount()!==1)throw new OperationConflict('La política cambió en otra sesión.');}
    public function setDiscountPolicyStatus(int$id,int$expectedVersion,bool$active):void{$s=$this->pdo()->prepare('UPDATE discount_policies SET is_active=:active,lock_version=lock_version+1 WHERE id=:id AND lock_version=:version');$s->execute(['active'=>$active?1:0,'id'=>self::id($id),'version'=>$expectedVersion]);if($s->rowCount()!==1)throw new OperationConflict('La política cambió en otra sesión.');}
    private function periodOverlap(string$table,string$scope,array$params,string$from,?string$until,?int$exclude):bool{$sql="SELECT id FROM $table WHERE $scope AND is_active=1 AND valid_from<=COALESCE(:until,'9999-12-31') AND COALESCE(valid_until,'9999-12-31')>=:from".($exclude===null?'':' AND id<>:exclude').' LIMIT 1 FOR UPDATE';$params['until']=$until;$params['from']=$from;if($exclude!==null)$params['exclude']=self::id($exclude);$s=$this->pdo()->prepare($sql);$s->execute($params);return$s->fetchColumn()!==false;}
    private function one(string$sql,array$params):?array{$s=$this->pdo()->prepare($sql);$s->execute($params);$r=$s->fetch();return is_array($r)?$r:null;}
    private function assertTable(string$table,array$allowed):void{if(!in_array($table,$allowed,true))throw new \InvalidArgumentException('Tabla de configuración no permitida.');}
    private function assertPeriod(string$t,string$f,string$r):void{if(!in_array([$t,$f,$r],[['tax_rates','tax_category_id','rate'],['price_list_rules','price_list_id','discount_rate']],true))throw new \InvalidArgumentException('Regla de configuración no permitida.');}
}
